/*
 * vc4_gen.c - the generic QPU kernels for the numeric op long tail.
 *
 * One code path per kernel family, all generated by kgen.py's kops module:
 *
 *   uop     unary math          exp/log/sqrt/rcp/erf/tanh/sin/cos/abs/neg/
 *                               floor/ceil/round/sign/clip/leakyrelu/elu/
 *                               selu/softplus/softsign/gelu(x2)/hard*(x2)
 *   sel3    three-operand select where / clip-by-tensor / prelu
 *   gather  table-driven copy   out[o] = arena[tab[o]]  (every layout op)
 *   blit    contiguous copy     64 B per group, no table
 *   reduce  strided reduction   sum/mean/max/min/argmax/argmin
 *   cumsum  inclusive prefix sum over the last axis
 *
 * The CPU only moves bytes here (padding a tail, copying a result back) and
 * builds index tables from *integer* metadata; no activation arithmetic runs
 * on the ARM.  Every kernel is element-verified against a float64 reference by
 * tests/test_genops.c.
 */
#define _GNU_SOURCE
#include "vc4_int.h"

#include <stdio.h>
#include <string.h>

/* ------------------------------------------------------------------ helpers */
static int uop_nvec(vc4_uop op)
{
    switch (op) {
    /* The nv8 two-chunk store hit a second hardware fault (a constant 2^92
     * scale; docs/ONNX.md 12.5), so exp/log/round use the verified 4-vector
     * path.  Round is 641 words there and does not need the split. */
    /* only the bodies that do not fit the 16-vector 16 KiB code slot: */
    case VC4_UOP_SELU: case VC4_UOP_SOFTPLUS:
    case VC4_UOP_GELU: case VC4_UOP_GELU_ERF: case VC4_UOP_SIN:
    case VC4_UOP_COS: case VC4_UOP_SQRT:
    case VC4_UOP_RECIPROCAL: case VC4_UOP_MISH:
    case VC4_UOP_TANH: case VC4_UOP_ERF: case VC4_UOP_ELU:
    case VC4_UOP_EXP: case VC4_UOP_LOG: case VC4_UOP_ROUND:
    /* inverse / hyperbolic (docs/OPS-UNARY.md): asin/acos/atan are the
     * shortest, but the 16-vector copy of every one of them is over 28 KiB */
    case VC4_UOP_ACOS: case VC4_UOP_ACOSH: case VC4_UOP_ASIN:
    case VC4_UOP_ASINH: case VC4_UOP_ATAN: case VC4_UOP_ATANH:
    case VC4_UOP_TAN: case VC4_UOP_SINH: case VC4_UOP_COSH:
        return 4;
    default:
        return 16;
    }
}

static const char *uop_name(vc4_uop op)
{
    switch (op) {
    case VC4_UOP_ABS: return "abs";
    case VC4_UOP_NEG: return "neg";
    case VC4_UOP_IDENTITY: return "identity";
    case VC4_UOP_CLIP: return "clip";
    case VC4_UOP_LEAKYRELU: return "leakyrelu";
    case VC4_UOP_FLOOR: return "floor";
    case VC4_UOP_CEIL: return "ceil";
    case VC4_UOP_ROUND: return "round";
    case VC4_UOP_SIGN: return "sign";
    case VC4_UOP_EXP: return "exp";
    case VC4_UOP_LOG: return "log";
    case VC4_UOP_SQRT: return "sqrt";
    case VC4_UOP_RECIPROCAL: return "reciprocal";
    case VC4_UOP_TANH: return "tanh";
    case VC4_UOP_ERF: return "erf";
    case VC4_UOP_ELU: return "elu";
    case VC4_UOP_SELU: return "selu";
    case VC4_UOP_SOFTPLUS: return "softplus";
    case VC4_UOP_SOFTSIGN: return "softsign";
    case VC4_UOP_GELU: return "gelu";
    case VC4_UOP_GELU_ERF: return "gelu_erf";
    case VC4_UOP_HARDSIGMOID: return "hardsigmoid";
    case VC4_UOP_HARDSWISH: return "hardswish";
    case VC4_UOP_SIN: return "sin";
    case VC4_UOP_COS: return "cos";
    case VC4_UOP_AFFINE: return "affine";
    case VC4_UOP_MISH: return "mish";
    case VC4_UOP_RNG: return "rng";
    case VC4_UOP_ACOS: return "acos";
    case VC4_UOP_ACOSH: return "acosh";
    case VC4_UOP_ASIN: return "asin";
    case VC4_UOP_ASINH: return "asinh";
    case VC4_UOP_ATAN: return "atan";
    case VC4_UOP_ATANH: return "atanh";
    case VC4_UOP_TAN: return "tan";
    case VC4_UOP_SINH: return "sinh";
    case VC4_UOP_COSH: return "cosh";
    default: return NULL;
    }
}

typedef void (*uni_fill)(uint32_t *u, uint32_t group, uint32_t nq,
                         const uint32_t *base);

static vc4_status launch_groups(vc4_ctx *ctx, const char *prefix,
                                char *const argv[], uint32_t ngroups,
                                uni_fill fill, const uint32_t *base)
{
    if (!ngroups)
        return VC4_ERR_INVAL;
    vc4_status st = VC4_OK;
    for (uint32_t b = 0; b < ngroups && st == VC4_OK; b += VC4_MAX_QPU) {
        uint32_t left = ngroups - b;
        int nq = left < (uint32_t)VC4_MAX_QPU ? (int)left : VC4_MAX_QPU;
        vc4_kernel *k = NULL;
        /* the blob cache keys on the name and a cached kernel is rejected if a
         * later launch needs more QPUs than it was generated for, exactly like
         * the elementwise path's ew_<op>_q<nq> */
        char kname[80];
        snprintf(kname, sizeof(kname), "%s_q%d", prefix, nq);
        st = vc4__kernel(ctx, kname, argv, nq, &k);
        if (st != VC4_OK)
            break;
        for (int i = 0; i < nq; ++i) {
            uint32_t *u = vc4__uni(ctx, k, i);
            memset(u, 0, VC4_UNI_WORDS * sizeof(uint32_t));
            fill(u, b + (uint32_t)i, (uint32_t)nq, base);
        }
        uint64_t ns = 0;
        st = vc4__launch(ctx, k, nq, &ns);
        ctx->st.kernel_ns += ns;
    }
    return st;
}

/* Bytes of a stream padded to `np` floats, mirrored into scratch when needed.
 * Only a tail copy: no arithmetic. */
static vc4_status pad_stream(vc4_ctx *ctx, const vc4_buf *b, size_t n,
                             size_t np, uint32_t *bus)
{
    *bus = vc4_bus_addr(ctx, b);
    if (np == n)
        return VC4_OK;
    float *t = vc4__scratch_alloc(ctx, np * 4, NULL);
    if (!t)
        return VC4_ERR_NOMEM;
    /* the source is arena data the QPU may have written: drop our cached
     * copies before reading it, exactly like vc4_download does */
    vc4__invalidate_off(ctx, b->off, n * 4);
    vc4__write(ctx, (uint32_t)((uint8_t *)t - ctx->arena),
               ctx->arena + b->off, n * 4);
    memset((uint8_t *)t + n * 4, 0, (np - n) * 4);
    vc4__mark_dirty(ctx, (uint32_t)((uint8_t *)t - ctx->arena), np * 4);
    *bus = ctx->gpu_bus + (uint32_t)((uint8_t *)t - ctx->arena);
    return VC4_OK;
}

/* --------------------------------------------------------------------- uop */
struct uop_base {
    uint32_t a_bus, o_bus, p0, p1, p2;
};

static void uop_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    /* build_ew's ABI: u0 a, u1 b, u2 out, u3 groups, u4 qpu, u5 nqpu, then the
     * op parameters (read by kops.ew_consts after the harness reads). */
    const struct uop_base *x = (const struct uop_base *)b;
    u[0] = x->a_bus;
    u[1] = x->a_bus;                  /* b stream unused: alias it to a */
    u[2] = x->o_bus;
    u[3] = 1;                         /* one group per QPU per launch */
    u[4] = g;
    u[5] = nq;
    u[6] = x->p0;
    u[7] = x->p1;
    u[8] = x->p2;
}

vc4_status vc4_unary(vc4_ctx *ctx, vc4_uop op, const vc4_buf *a, vc4_buf *out,
                     size_t n, float p0, float p1, float p2)
{
    if (!ctx || !a || !out || !n)
        return VC4_ERR_INVAL;
    if (op < 0 || op >= VC4_UOP_COUNT || !uop_name(op)) {
        vc4__set_err(ctx, "vc4_unary: unary op %d is not implemented", (int)op);
        return VC4_ERR_UNSUPPORTED;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    if (a->bytes < n * 4 || out->bytes < n * 4)
        return VC4_ERR_INVAL;
    /* The non-16 group path was element-verified on 2026-11-20: 0
     * mismatches over 105,264 elements for the whole unary family, five
     * shapes each (docs/NUMERICS.md, docs/ONNX.md sec. 12.3). */
    int nvec = uop_nvec(op);
    size_t per = (size_t)16 * nvec;
    size_t ngroups = (n + per - 1) / per;
    size_t np = ngroups * per;

    /* Many small shapes: the input must be routed through scratch for the
     * padded tail, the output always is. */
    vc4__scratch_reset(ctx);
    struct uop_base x;
    float p[3] = { p0, p1, p2 };
    memcpy(&x.p0, &p[0], 4);
    memcpy(&x.p1, &p[1], 4);
    memcpy(&x.p2, &p[2], 4);
    vc4_status st = pad_stream(ctx, a, n, np, &x.a_bus);
    if (st != VC4_OK) {
        vc4__scratch_reset(ctx);
        return st;
    }
    float *o_tmp = NULL;
    x.o_bus = vc4_bus_addr(ctx, out);
    if (np != n) {
        o_tmp = vc4__scratch_alloc(ctx, np * 4, NULL);
        if (!o_tmp) {
            vc4__scratch_reset(ctx);
            return VC4_ERR_NOMEM;
        }
        x.o_bus = ctx->gpu_bus + (uint32_t)((uint8_t *)o_tmp - ctx->arena);
    }
    char name[64];
    char nv[8];
    snprintf(name, sizeof(name), "uop_%s_v%d", uop_name(op), nvec);
    snprintf(nv, sizeof(nv), "%d", nvec);
    char *argv[] = { (char *)"uop", (char *)"--op", (char *)uop_name(op),
                     (char *)"--nvec", nv, NULL };
    st = launch_groups(ctx, name, argv, (uint32_t)ngroups, uop_fill,
                       (const uint32_t *)&x);
    if (st == VC4_OK) {
        ctx->st.flops += (uint64_t)n * 4;
        if (o_tmp) {
            vc4__l2_flush(ctx);
            vc4__write(ctx, out->off, o_tmp, n * 4);
        }
    }
    vc4__scratch_reset(ctx);
    return st;
}

/* ------------------------------------------------------------------- probe */
struct probe_base {
    uint32_t a, o;
};

static void probe_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct probe_base *x = (const struct probe_base *)b;
    u[0] = x->a;
    u[1] = x->a;                  /* unused stream: alias, never load from 0 */
    u[2] = x->o;
    u[3] = 1;
    u[4] = g;
    u[5] = nq;
}

vc4_status vc4_probe(vc4_ctx *ctx, const char *seq, const vc4_buf *a,
                     vc4_buf *out, size_t n)
{
    if (!ctx || !seq || !a || !out || n != 16)
        return VC4_ERR_INVAL;
    if (a->bytes < 16 * 4 || out->bytes < 4 * 16 * 4)
        return VC4_ERR_INVAL;
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    struct probe_base x = { vc4_bus_addr(ctx, a), vc4_bus_addr(ctx, out) };
    char name[96];
    snprintf(name, sizeof(name), "probe_%s_q1", seq);
    char *argv[] = { (char *)"probe_seq", (char *)"--seq", (char *)seq, NULL };
    return launch_groups(ctx, name, argv, 1, probe_fill,
                         (const uint32_t *)&x);
}

/* -------------------------------------------------------------------- sel3 */
struct sel3_base {
    uint32_t a, b, c, o;
};

static void sel3_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct sel3_base *x = (const struct sel3_base *)b;
    u[0] = x->a;
    u[1] = x->o;
    u[2] = 1;
    u[3] = g;
    u[4] = nq;
    u[5] = x->b;
    u[6] = x->c;
    u[7] = 0;
}

vc4_status vc4_select3(vc4_ctx *ctx, vc4_selop op, const vc4_buf *a,
                       const vc4_buf *b, const vc4_buf *c, vc4_buf *out,
                       size_t n)
{
    const char *nms[] = { "where", "clip3", "prelu" };
    if (!ctx || !a || !b || !c || !out || !n)
        return VC4_ERR_INVAL;
    {
        vc4_status g = vc4__refuse_unverified(ctx, "vc4_select3",
            "it shares the pad_stream/TMU lane pattern of vc4_reduce: WHERE "
            "returns VC4_OK with every element wrong (measured on 2026-11-20, "
            "one launch per process)");
        if (g != VC4_OK)
            return g;
    }
    if (op < 0 || op > 2) {
        vc4__set_err(ctx, "vc4_select3: op %d is not implemented", (int)op);
        return VC4_ERR_UNSUPPORTED;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    if (a->bytes < n * 4 || b->bytes < n * 4 || c->bytes < n * 4 ||
        out->bytes < n * 4)
        return VC4_ERR_INVAL;
    const size_t per = 256;
    size_t ngroups = (n + per - 1) / per;
    size_t np = ngroups * per;
    vc4__scratch_reset(ctx);
    struct sel3_base x;
    vc4_status st = pad_stream(ctx, a, n, np, &x.a);
    if (st == VC4_OK)
        st = pad_stream(ctx, b, n, np, &x.b);
    if (st == VC4_OK)
        st = pad_stream(ctx, c, n, np, &x.c);
    float *o_tmp = NULL;
    x.o = vc4_bus_addr(ctx, out);
    if (st == VC4_OK && np != n) {
        o_tmp = vc4__scratch_alloc(ctx, np * 4, NULL);
        if (!o_tmp) {
            st = VC4_ERR_NOMEM;
        } else {
            x.o = ctx->gpu_bus + (uint32_t)((uint8_t *)o_tmp - ctx->arena);
        }
    }
    if (st == VC4_OK) {
        char name[64];
        snprintf(name, sizeof(name), "sel3_%s", nms[op]);
        char *argv[] = { (char *)"sel3", (char *)"--op", (char *)nms[op],
                         NULL };
        st = launch_groups(ctx, name, argv, (uint32_t)ngroups, sel3_fill,
                           (const uint32_t *)&x);
    }
    if (st == VC4_OK) {
        ctx->st.flops += (uint64_t)n * 2;
        if (o_tmp) {
            vc4__l2_flush(ctx);
            vc4__write(ctx, out->off, o_tmp, n * 4);
        }
    }
    vc4__scratch_reset(ctx);
    return st;
}

/* ------------------------------------------------------------------ gather */
struct gather_base {
    uint32_t tab, o, base, fill;
};

static void gather_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct gather_base *x = (const struct gather_base *)b;
    u[0] = x->tab;
    u[1] = x->o;
    u[2] = 1;
    u[3] = g;
    u[4] = nq;
    u[5] = x->base;
    u[6] = x->fill;
}

vc4_status vc4_gather(vc4_ctx *ctx, const vc4_buf *tab, vc4_buf *out,
                      size_t n, float fill)
{
    if (!ctx || !tab || !out || !n)
        return VC4_ERR_INVAL;
    {
        vc4_status g = vc4__refuse_unverified(ctx, "vc4_gather",
            "the TMU1 setup word takes its address from an accumulator and "
            "its load/pop order does not match build_ew; it wedges the QPU");
        if (g != VC4_OK)
            return g;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    if (tab->bytes < n * 4 || out->bytes < n * 4)
        return VC4_ERR_INVAL;
    const size_t per = 256;
    size_t ngroups = (n + per - 1) / per;
    size_t np = ngroups * per;
    vc4__scratch_reset(ctx);
    struct gather_base x;
    x.base = ctx->gpu_bus;
    memcpy(&x.fill, &fill, 4);
    /* the table is int32 byte offsets from the arena base; a padded tail
     * points at -1 (the fill slot) so no read leaves the arena */
    if (np != n) {
        int32_t *t = vc4__scratch_alloc(ctx, np * 4, NULL);
        if (!t) {
            vc4__scratch_reset(ctx);
            return VC4_ERR_NOMEM;
        }
        vc4__invalidate_off(ctx, tab->off, n * 4);
        vc4__write(ctx, (uint32_t)((uint8_t *)t - ctx->arena),
                   ctx->arena + tab->off, n * 4);
        for (size_t i = n; i < np; ++i)
            t[i] = -1;
        x.tab = ctx->gpu_bus + (uint32_t)((uint8_t *)t - ctx->arena);
    } else {
        x.tab = vc4_bus_addr(ctx, tab);
    }
    float *o_tmp = NULL;
    x.o = vc4_bus_addr(ctx, out);
    vc4_status st = VC4_OK;
    if (np != n) {
        o_tmp = vc4__scratch_alloc(ctx, np * 4, NULL);
        if (!o_tmp) {
            st = VC4_ERR_NOMEM;
        } else {
            x.o = ctx->gpu_bus + (uint32_t)((uint8_t *)o_tmp - ctx->arena);
        }
    }
    if (st == VC4_OK) {
        char *argv[] = { (char *)"gather", NULL };
        st = launch_groups(ctx, "gather_v16", argv, (uint32_t)ngroups,
                           gather_fill, (const uint32_t *)&x);
    }
    if (st == VC4_OK) {
        ctx->st.flops += n;
        if (o_tmp) {
            vc4__l2_flush(ctx);
            vc4__write(ctx, out->off, o_tmp, n * 4);
        }
    }
    vc4__scratch_reset(ctx);
    return st;
}

/* -------------------------------------------------------------------- blit */
struct blit_base {
    uint32_t a, o;
};

static void blit_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct blit_base *x = (const struct blit_base *)b;
    u[0] = x->a;
    u[1] = x->o;
    u[2] = 1;
    u[3] = g;
    u[4] = nq;
}

vc4_status vc4_blit(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out, size_t bytes)
{
    if (!ctx || !a || !out || !bytes)
        return VC4_ERR_INVAL;
    {
        vc4_status g = vc4__refuse_unverified(ctx, "vc4_blit",
            "it uses build_ew's 4-vector store path, which writes no output");
        if (g != VC4_OK)
            return g;
    }
    if (bytes % 64) {
        vc4__set_err(ctx, "vc4_blit: %zu bytes is not a multiple of 64 B; the "
                     "gather table handles unaligned copies", bytes);
        return VC4_ERR_UNSUPPORTED;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    if (a->bytes < bytes || out->bytes < bytes)
        return VC4_ERR_INVAL;
    struct blit_base x;
    x.a = vc4_bus_addr(ctx, a);
    x.o = vc4_bus_addr(ctx, out);
    char *argv[] = { (char *)"blit", NULL };
    uint32_t ngroups = (uint32_t)(bytes / 64);
    vc4_status st = launch_groups(ctx, "blit_v64", argv, ngroups, blit_fill,
                                  (const uint32_t *)&x);
    if (st == VC4_OK)
        ctx->st.flops += bytes / 4;
    return st;
}

/* ------------------------------------------------------------------ copy2d */
/* One launch covers every row: QPU q takes rows q, q+nqpu, ...  A row is
 * `nblk` blocks (bstep bytes apart in both streams) of `vpr` 16-word
 * vectors.  u3/u4 are the per-QPU row advances, i.e. nqpu*row - nblk*bstep,
 * because the block loop has already added nblk*bstep. */
static vc4_status copy2d_run(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                             uint32_t rows, uint32_t vpr, uint32_t srow,
                             uint32_t drow, uint32_t svec, uint32_t dvec,
                             uint32_t slane, uint32_t nlane, uint32_t nblk,
                             uint32_t sbstep, uint32_t dbstep, float vfill,
                             uint32_t units, uint32_t depth)
{
    if (!ctx || !out || !rows || !vpr)
        return VC4_ERR_INVAL;
    if (units != 1 && units != 2 && units != 4)
        return VC4_ERR_INVAL;
    if (depth < 1 || depth > 16)
        return VC4_ERR_INVAL;
    if (nlane > 16)
        return VC4_ERR_INVAL;
    if (!nblk)
        nblk = 1;
    if (!sbstep)
        sbstep = 64;
    if (!dbstep)
        dbstep = 64;
    if (vpr % units) {
        vc4__set_err(ctx, "vc4_copy2d: vpr=%u is not a multiple of units=%u "
                     "(one DMA store is units vectors)", vpr, units);
        return VC4_ERR_UNSUPPORTED;
    }
    if (dvec < 4 || dvec > 0xFFFF || (dvec & 3) || (units > 1 && dvec < 64)) {
        vc4__set_err(ctx, "vc4_copy2d: dvec=%u must be a 4-byte multiple in "
                     "4..65535 (>= 64 unless units==1, whose store has no "
                     "row stride)", dvec);
        return VC4_ERR_UNSUPPORTED;
    }
    if (nlane && nlane != 16 && (uint64_t)15 * slane >= (1u << 24)) {
        vc4__set_err(ctx, "vc4_copy2d: lane stride %u * 15 overflows the "
                     "24-bit address multiply", slane);
        return VC4_ERR_UNSUPPORTED;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    const uint64_t s_ext = (uint64_t)(rows - 1) * srow +
                           (uint64_t)(nblk - 1) * sbstep +
                           (uint64_t)(vpr - 1) * svec +
                           (uint64_t)(nlane ? nlane - 1 : 0) * slane + 4;
    const uint64_t d_ext = (uint64_t)(rows - 1) * drow +
                           (uint64_t)(nblk - 1) * dbstep +
                           (uint64_t)(vpr - 1) * dvec +
                           (uint64_t)depth * 4;
    if (nlane && a && s_ext > a->bytes) {
        vc4__set_err(ctx, "vc4_copy2d: source extent %llu B > buffer %u B "
                     "(rows=%u vpr=%u nblk=%u)", (unsigned long long)s_ext,
                     a->bytes, rows, vpr, nblk);
        return VC4_ERR_INVAL;
    }
    if (d_ext > out->bytes) {
        vc4__set_err(ctx, "vc4_copy2d: dest extent %llu B > buffer %u B "
                     "(rows=%u vpr=%u nblk=%u depth=%u)",
                     (unsigned long long)d_ext, out->bytes, rows, vpr, nblk,
                     depth);
        return VC4_ERR_INVAL;
    }

    uint32_t fillbits;
    char fillbuf[16], unitbuf[8], depthbuf[8];
    memcpy(&fillbits, &vfill, 4);
    snprintf(fillbuf, sizeof(fillbuf), "%u", fillbits);
    snprintf(unitbuf, sizeof(unitbuf), "%u", units);
    snprintf(depthbuf, sizeof(depthbuf), "%u", depth);
    char *argv[] = { (char *)"copy2d", (char *)"--fill", fillbuf,
                     (char *)"--units", unitbuf, (char *)"--depth", depthbuf,
                     NULL };
    char name[64];
    int nq = rows < (uint32_t)VC4_MAX_QPU ? (int)rows : VC4_MAX_QPU;
    vc4_kernel *k = NULL;
    snprintf(name, sizeof(name), "copy2d_v1_f%08x_u%u_d%u_q%d", fillbits,
             units, depth, nq);
    vc4_status st = vc4__kernel(ctx, name, argv, nq, &k);
    if (st != VC4_OK)
        return st;
    const uint32_t src_bus = nlane && a ? vc4_bus_addr(ctx, a)
                                        : vc4_bus_addr(ctx, out);
    const uint32_t dst_bus = vc4_bus_addr(ctx, out);
    for (int i = 0; i < nq; ++i) {
        uint32_t *u = vc4__uni(ctx, k, i);
        memset(u, 0, VC4_UNI_WORDS * sizeof(uint32_t));
        u[0] = src_bus + (uint32_t)((uint64_t)i * srow);
        u[1] = dst_bus + (uint32_t)((uint64_t)i * drow);
        u[2] = 1 + (rows - 1 - (uint32_t)i) / (uint32_t)nq;
        u[3] = (uint32_t)nq * srow;
        u[4] = (uint32_t)nq * drow;
        u[5] = vpr;
        u[6] = svec;
        u[7] = dvec;
        u[8] = slane;
        u[9] = 4u * (uint32_t)i;
        u[10] = (4u * (uint32_t)i) << 7;
        u[11] = nlane;
        u[12] = nblk;
        u[13] = sbstep;
        u[14] = dbstep;
        u[15] = units > 1 ? dvec - 64 : 0;
    }
    uint64_t ns = 0;
    st = vc4__launch(ctx, k, nq, &ns);
    ctx->st.kernel_ns += ns;
    if (st == VC4_OK)
        ctx->st.flops += (uint64_t)rows * nblk * vpr * 16;
    return st;
}

vc4_status vc4_copy2d(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                      uint32_t rows, uint32_t vpr, uint32_t srow,
                      uint32_t drow, uint32_t svec, uint32_t dvec,
                      uint32_t slane)
{
    if (!a || !slane)
        return VC4_ERR_INVAL;
    return copy2d_run(ctx, a, out, rows, vpr, srow, drow, svec, dvec, slane,
                      16, 1, 64, 64, 0.0f, 4, 16);
}

/* Same, with an explicit store shape (units vectors x depth words) and a
 * lane count: units=1, depth=k moves a row of k < 16 floats without writing
 * past it; nlane < 16 zero-pads channels. */
vc4_status vc4_copy2d_n(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                        uint32_t rows, uint32_t vpr, uint32_t srow,
                        uint32_t drow, uint32_t svec, uint32_t dvec,
                        uint32_t slane, uint32_t nlane, uint32_t units,
                        uint32_t depth)
{
    if (!a || !slane || !nlane || nlane > 16)
        return VC4_ERR_INVAL;
    return copy2d_run(ctx, a, out, rows, vpr, srow, drow, svec, dvec, slane,
                      nlane, 1, 64, 64, 0.0f, units, depth);
}

/* Same, with `nblk` 16-channel blocks per row, `bstep` bytes apart in both
 * streams: the channel concat/split of more than 16 channels per pixel. */
vc4_status vc4_copy2d_x(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                        uint32_t rows, uint32_t vpr, uint32_t srow,
                        uint32_t drow, uint32_t svec, uint32_t dvec,
                        uint32_t slane, uint32_t nlane, uint32_t nblk,
                        uint32_t sbstep, uint32_t dbstep, uint32_t units,
                        uint32_t depth)
{
    if (!a || !slane)
        return VC4_ERR_INVAL;
    return copy2d_run(ctx, a, out, rows, vpr, srow, drow, svec, dvec, slane,
                      nlane, nblk, sbstep, dbstep, 0.0f, units, depth);
}

vc4_status vc4_fill2d(vc4_ctx *ctx, vc4_buf *out, uint32_t rows, uint32_t vpr,
                      uint32_t drow, uint32_t dvec, float value)
{
    return copy2d_run(ctx, NULL, out, rows, vpr, 0, drow, 0, dvec, 0, 0, 1,
                      64, 64, value, 4, 16);
}

/* ------------------------------------------------------------------ reduce */
struct red_base {
    uint32_t a, o, red, op, vstr, ingap, lanestride;
    uint32_t inbase, outbase, outgap;
};

__attribute__((unused)) static void red_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct red_base *x = (const struct red_base *)b;
    uint32_t left = x->inbase;      /* unused; the fields below are absolute */
    (void)left;
    u[0] = x->a;
    u[1] = x->o;
    u[2] = 1;
    u[3] = g;
    u[4] = nq;
    u[5] = x->red;
    u[6] = x->op;
    u[7] = x->vstr;
    u[8] = g * x->vstr * 16;        /* group byte offset in the input  */
    u[9] = g * 1024;                /* group byte offset in the output */
    u[10] = x->ingap;
    u[11] = x->outgap;
    u[12] = x->outgap;
    u[13] = x->lanestride;
}

vc4_status vc4_reduce(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                      uint32_t outer, uint32_t red, vc4_redop op)
{
    static const char *nms[] = { "sum", "mean", "max", "min", "argmax",
                                 "argmin" };
    if (!ctx || !a || !out)
        return VC4_ERR_INVAL;
    {
        vc4_status g = vc4__refuse_unverified(ctx, "vc4_reduce",
            "it walks a fixed 256-output group (reading past the caller's "
            "buffer into unmapped memory) and seeds r4 instead of r0; every "
            "shape, including outer=256 red=16, kills the QPU context");
        if (g != VC4_OK)
            return g;
    }
    if (op < 0 || op > 5) {
        vc4__set_err(ctx, "vc4_reduce: op %d is not implemented", (int)op);
        return VC4_ERR_UNSUPPORTED;
    }
    if (!outer || !red) {
        vc4__set_err(ctx, "vc4_reduce: outer=%u red=%u is not reducible",
                     outer, red);
        return VC4_ERR_UNSUPPORTED;
    }
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    /* the kernel walks 16 outputs per vector, 16 vectors per group */
    size_t ngroups = (outer + 255) / 256;
    size_t np = ngroups * 256;
    if (a->bytes < (size_t)outer * red * 4)
        return VC4_ERR_INVAL;
    if (out->bytes < (size_t)outer * 4)
        return VC4_ERR_INVAL;
    if ((uint64_t)red * 4 * 16 > 0xFFFFFF) {
        vc4__set_err(ctx, "vc4_reduce: red=%u needs %llu B per lane stride; "
                     "24-bit address math limits red*64 to 16 MiB",
                     red, (unsigned long long)red * 64);
        return VC4_ERR_UNSUPPORTED;
    }
    struct red_base x;
    x.a = vc4_bus_addr(ctx, a);
    x.red = red;
    x.op = (uint32_t)op;
    x.vstr = red * 64;                     /* 16 outputs x red floats x 4 B */
    x.lanestride = red * 4;
    x.ingap = 0;
    x.outgap = 0;
    float *o_tmp = NULL;
    vc4__scratch_reset(ctx);
    x.o = vc4_bus_addr(ctx, out);
    if (np != outer) {
        /* The kernel walks a full 256-output group, so it reads
         * np*red floats even when only `outer` outputs are real.  Reading
         * past the end of the caller's buffer can leave the arena (the last
         * buffer is usually at the top) and a TMU read of an unmapped
         * physical address wedges the QPU.  Pad the tail in scratch; the
         * padding outputs are discarded, so their values do not matter. */
        float *ap = vc4__scratch_alloc(ctx, np * (size_t)red * 4, NULL);
        if (!ap) {
            vc4__scratch_reset(ctx);
            return VC4_ERR_NOMEM;
        }
        vc4__invalidate_off(ctx, a->off, (size_t)outer * red * 4);
        vc4__write(ctx, (uint32_t)((uint8_t *)ap - ctx->arena),
                   ctx->arena + a->off, (size_t)outer * red * 4);
        memset((uint8_t *)ap + (size_t)outer * red * 4, 0,
               (np - outer) * (size_t)red * 4);
        vc4__mark_dirty(ctx, (uint32_t)((uint8_t *)ap - ctx->arena),
                        np * (size_t)red * 4);
        x.a = ctx->gpu_bus + (uint32_t)((uint8_t *)ap - ctx->arena);
        o_tmp = vc4__scratch_alloc(ctx, np * 4, NULL);
        if (!o_tmp) {
            vc4__scratch_reset(ctx);
            return VC4_ERR_NOMEM;
        }
        x.o = ctx->gpu_bus + (uint32_t)((uint8_t *)o_tmp - ctx->arena);
    }
    char name[64];
    snprintf(name, sizeof(name), "reduce_%s", nms[op]);
    char *argv[] = { (char *)"reduce", (char *)"--op", (char *)nms[op], NULL };
    /* groups are interleaved q, q+nq, ...; the input/output group offsets are
     * computed per QPU inside red_fill from the global group index. */
    vc4_status st = VC4_OK;
    for (uint32_t b = 0; b < (uint32_t)ngroups && st == VC4_OK;
         b += VC4_MAX_QPU) {
        uint32_t left = (uint32_t)ngroups - b;
        int nq = left < (uint32_t)VC4_MAX_QPU ? (int)left : VC4_MAX_QPU;
        vc4_kernel *k = NULL;
        st = vc4__kernel(ctx, name, argv, nq, &k);
        if (st != VC4_OK)
            break;
        for (int i = 0; i < nq; ++i) {
            uint32_t *u = vc4__uni(ctx, k, i);
            uint32_t g = b + (uint32_t)i;
            uint32_t gl = (uint32_t)i;
            uint32_t nql = (uint32_t)nq;
            memset(u, 0, VC4_UNI_WORDS * sizeof(uint32_t));
            u[0] = x.a;
            u[1] = x.o;
            u[2] = 1 + ((uint32_t)ngroups - 1 - gl) / nql;
            u[3] = g;
            u[4] = nql;
            u[5] = x.red;
            u[6] = x.op;
            u[7] = x.vstr;
            u[8] = g * x.vstr * 16;        /* input base for this group   */
            u[9] = g * 1024;               /* output base                 */
            u[10] = (nql - 1) * x.vstr * 16;
            u[11] = (nql - 1) * 1024;
            u[12] = (nql - 1) * 1024;
            u[13] = x.lanestride;
        }
        uint64_t ns = 0;
        st = vc4__launch(ctx, k, nq, &ns);
        ctx->st.kernel_ns += ns;
    }
    if (st == VC4_OK) {
        ctx->st.flops += (uint64_t)outer * red;
        if (o_tmp) {
            vc4__l2_flush(ctx);
            vc4__write(ctx, out->off, o_tmp, (size_t)outer * 4);
        }
    }
    vc4__scratch_reset(ctx);
    return st;
}

/* ------------------------------------------------------------------ cumsum */
struct csum_base {
    uint32_t a, o;
};

static void csum_fill(uint32_t *u, uint32_t g, uint32_t nq, const uint32_t *b)
{
    const struct csum_base *x = (const struct csum_base *)b;
    u[0] = x->a;
    u[1] = x->o;
    u[2] = 1;
    u[3] = g;
    u[4] = nq;
}

vc4_status vc4_cumsum(vc4_ctx *ctx, const vc4_buf *a, vc4_buf *out,
                      uint32_t rows, uint32_t cols)
{
    if (!ctx || !a || !out || !rows || !cols)
        return VC4_ERR_INVAL;
    {
        vc4_status g = vc4__refuse_unverified(ctx, "vc4_cumsum",
            "it uses the TMU setup that wedges vc4_gather; every shape kills "
            "the QPU context (measured on 2026-11-20, one launch per process)");
        if (g != VC4_OK)
            return g;
    }
    if (cols % 256) {
        vc4__set_err(ctx, "vc4_cumsum: cols=%u is not a multiple of 256; pad "
                     "the scan axis on the host (byte fill) first", cols);
        return VC4_ERR_UNSUPPORTED;
    }
    if (a->bytes < (size_t)rows * cols * 4 ||
        out->bytes < (size_t)rows * cols * 4)
        return VC4_ERR_INVAL;
    if (ctx->dead)
        return VC4_ERR_TIMEOUT;
    struct csum_base x;
    x.a = vc4_bus_addr(ctx, a);
    x.o = vc4_bus_addr(ctx, out);
    char *argv[] = { (char *)"cumsum", NULL };
    uint32_t ngroups = rows * (cols / 256);
    vc4_status st = launch_groups(ctx, "cumsum_v16", argv, ngroups, csum_fill,
                                  (const uint32_t *)&x);
    if (st == VC4_OK)
        ctx->st.flops += (uint64_t)rows * cols;
    return st;
}
